package com.trainflow.pricing; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface TrainingPricingRepository extends JpaRepository<TrainingPricing,UUID>{Optional<TrainingPricing>findByTrainingCaseId(UUID id);@Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE)@Query("select p from TrainingPricing p where p.trainingCaseId=:id")Optional<TrainingPricing>locked(@Param("id")UUID id);}
